#!/bin/bash
set -euo pipefail

DEV="${1:-}"
BOARD="${2:-}"

if [ -z "$DEV" ] || [ ! -b "$DEV" ]; then
  echo "Error: Specify block device, e.g. $0 /dev/sdb [board]"
  exit 1
fi

if [ -z "$BOARD" ]; then
  echo "Detecting board automatically or default to cubie-a7a..."
  BOARD="cubie-a7a"
fi

TMP_PAYLOAD="/tmp/payload_$$"
mkdir -p "$TMP_PAYLOAD"

cleanup() {
  rm -rf "$TMP_PAYLOAD"
}
trap cleanup EXIT

echo "[*] Extracting payload..."
PAYLOAD_LINE=$(grep -a -n "^__PAYLOAD_START__$" "$0" | cut -d: -f1)
if [ -n "$PAYLOAD_LINE" ]; then
  tail -n +$((PAYLOAD_LINE + 1)) "$0" | base64 -d | tar -xz -C "$TMP_PAYLOAD"
else
  # Running unpacked from directory
  cp -r /srv/storage/fix_bundle/* "$TMP_PAYLOAD/" 2>/dev/null || true
fi

echo "[*] Selected board: $BOARD"
DTB_NAME="sun60i-a733-cubie-a7a.dtb"
BOOTLOADER_FILE="$TMP_PAYLOAD/bootloader-radxa-cubie.bin"
LOGIN_USER="radxa"

if [ "$BOARD" = "bananapi-m8" ]; then
  DTB_NAME="sun60i-a733-bananapi-m8.dtb"
  BOOTLOADER_FILE="$TMP_PAYLOAD/bootloader-bananapi-m8.bin"
  LOGIN_USER="bananapi"
elif [ "$BOARD" = "cubie-a7s" ]; then
  DTB_NAME="sun60i-a733-cubie-a7s.dtb"
  BOOTLOADER_FILE="$TMP_PAYLOAD/bootloader-radxa-cubie.bin"
  LOGIN_USER="radxa"
elif [ "$BOARD" = "opi4pro" ]; then
  DTB_NAME="sun60i-a733-orangepi-4-pro.dtb"
  BOOTLOADER_FILE="$TMP_PAYLOAD/bootloader-orangepi-4-pro.bin"
  LOGIN_USER="orangepi"
fi

echo "[*] Writing universal sector 16 bootloader ($BOOTLOADER_FILE)..."
if [ -f "$BOOTLOADER_FILE" ]; then
  dd if="$BOOTLOADER_FILE" of="$DEV" bs=512 seek=16 status=progress conv=fsync
fi

echo "[*] Mounting root filesystem on ${DEV}p1..."
MNT="/mnt/sdcard_$$"
mkdir -p "$MNT"
mount "${DEV}p1" "$MNT"
sync_cleanup() {
  sync
  umount "$MNT" 2>/dev/null || true
  rmdir "$MNT" 2>/dev/null || true
  rm -rf "$TMP_PAYLOAD"
}
trap sync_cleanup EXIT

# Copy DTB files
KVER=$(ls "$MNT/boot/" 2>/dev/null | grep '^vmlinux-' | head -n1 | sed 's/^vmlinux-//' || echo "6.18.63-sun60iw2")
mkdir -p "$MNT/boot/dtb/allwinner" "$MNT/boot/dtb-$KVER/allwinner"

for dtb in sun60i-a733-cubie-a7a.dtb sun60i-a733-cubie-a7s.dtb sun60i-a733-orangepi-4-pro.dtb sun60i-a733-bananapi-m8.dtb; do
  if [ -f "$TMP_PAYLOAD/$dtb" ]; then
    cp -f "$TMP_PAYLOAD/$dtb" "$MNT/boot/dtb/allwinner/"
    cp -f "$TMP_PAYLOAD/$dtb" "$MNT/boot/dtb-$KVER/allwinner/"
    cp -f "$TMP_PAYLOAD/$dtb" "$MNT/boot/"
  fi
done

# Install kernel drivers (Maxio PHY, AIC8800 Wi-Fi, SocketCAN)
MOD_DIR="$MNT/lib/modules/$KVER"
if [ -d "$MOD_DIR" ]; then
  echo "[*] Installing hardware drivers into $MOD_DIR..."
  mkdir -p "$MOD_DIR/kernel/drivers/net/phy" "$MOD_DIR/kernel/drivers/net/wireless/aic8800" "$MOD_DIR/kernel/drivers/net/can" "$MOD_DIR/kernel/drivers/net/can/usb"
  [ -f "$TMP_PAYLOAD/maxio.ko" ] && cp -f "$TMP_PAYLOAD/maxio.ko" "$MOD_DIR/kernel/drivers/net/phy/"
  [ -f "$TMP_PAYLOAD/aic8800_bsp.ko" ] && cp -f "$TMP_PAYLOAD/aic8800_bsp.ko" "$MOD_DIR/kernel/drivers/net/wireless/aic8800/"
  [ -f "$TMP_PAYLOAD/aic8800_fdrv.ko" ] && cp -f "$TMP_PAYLOAD/aic8800_fdrv.ko" "$MOD_DIR/kernel/drivers/net/wireless/aic8800/"
  [ -f "$TMP_PAYLOAD/aic8800_btlpm.ko" ] && cp -f "$TMP_PAYLOAD/aic8800_btlpm.ko" "$MOD_DIR/kernel/drivers/net/wireless/aic8800/"
  [ -f "$TMP_PAYLOAD/can.ko" ] && cp -f "$TMP_PAYLOAD/can.ko" "$MOD_DIR/kernel/drivers/net/can/"
  [ -f "$TMP_PAYLOAD/can-raw.ko" ] && cp -f "$TMP_PAYLOAD/can-raw.ko" "$MOD_DIR/kernel/drivers/net/can/"
  [ -f "$TMP_PAYLOAD/can-dev.ko" ] && cp -f "$TMP_PAYLOAD/can-dev.ko" "$MOD_DIR/kernel/drivers/net/can/"
  [ -f "$TMP_PAYLOAD/gs_usb.ko" ] && cp -f "$TMP_PAYLOAD/gs_usb.ko" "$MOD_DIR/kernel/drivers/net/can/usb/"
  which depmod >/dev/null 2>&1 && depmod -b "$MNT" "$KVER" || true
fi

# Firmware
mkdir -p "$MNT/lib/firmware/aic8800d80"
[ -d "$TMP_PAYLOAD/a733-config" ] && cp -r "$TMP_PAYLOAD/a733-config"/* "$MNT/etc/" 2>/dev/null || true

# Completely purge plymouth, bootsplash, spinner services & kernel modules
echo "[*] Purging bootsplash, plymouth and spinner completely..."
rm -f "$MNT/etc/systemd/system/"*bootsplash* "$MNT/etc/systemd/system/"*spinner* "$MNT/etc/systemd/system/"*splash* 2>/dev/null || true
rm -f "$MNT/usr/lib/systemd/system/"*bootsplash* "$MNT/usr/lib/systemd/system/"*spinner* "$MNT/usr/lib/systemd/system/"*splash* 2>/dev/null || true
rm -f "$MNT/lib/systemd/system/"*bootsplash* "$MNT/lib/systemd/system/"*spinner* "$MNT/lib/systemd/system/"*splash* 2>/dev/null || true
rm -rf "$MNT/etc/systemd/system/"*target.wants/*bootsplash* "$MNT/etc/systemd/system/"*target.wants/*spinner* 2>/dev/null || true
rm -rf "$MNT/etc/systemd/system/"*target.wants/*plymouth* 2>/dev/null || true
rm -f "$MNT/usr/local/bin/"*spinner* "$MNT/usr/local/bin/"*splash* 2>/dev/null || true
rm -f "$MNT/lib/firmware/bootsplash"* "$MNT/usr/lib/firmware/bootsplash"* 2>/dev/null || true

# Mask plymouth services so nothing waits on them
for s in plymouth plymouth-start plymouth-quit plymouth-quit-wait plymouth-read-write; do
  ln -sf /dev/null "$MNT/etc/systemd/system/${s}.service" 2>/dev/null || true
done

# Install clean reference boot.cmd and boot.scr
echo "[*] Restoring verified standard reference boot.cmd & boot.scr..."
cp -f "$TMP_PAYLOAD/ref_boot.cmd" "$MNT/boot/boot.cmd"
cp -f "$TMP_PAYLOAD/ref_boot.scr" "$MNT/boot/boot.scr"

# Create clean orangepiEnv.txt and radxaEnv.txt with cpuidle fix
cat << ENV_EOF > "$MNT/boot/orangepiEnv.txt"
verbosity=7
bootlogo=false
console=both
earlycon=on
overlay_prefix=sun60i-a733
fdtfile=allwinner/$DTB_NAME
rootdev=/dev/mmcblk0p1
rootfstype=ext4
extraargs=cma=256M cpuidle.off=1
ENV_EOF
cp -f "$MNT/boot/orangepiEnv.txt" "$MNT/boot/radxaEnv.txt"
cp -f "$MNT/boot/orangepiEnv.txt" "$MNT/boot/bananapiEnv.txt"
cp -f "$MNT/boot/orangepiEnv.txt" "$MNT/boot/a733-allwinnerEnv.txt"

# Execute the proper branding script
if [ -f "$TMP_PAYLOAD/update-radxa-branding.sh" ] && [ "$BOARD" != "bananapi-m8" ] && [ "$BOARD" != "opi4pro" ]; then
  echo "[*] Executing Radxa branding script for $BOARD..."
  chmod +x "$TMP_PAYLOAD/update-radxa-branding.sh"
  "$TMP_PAYLOAD/update-radxa-branding.sh" "$MNT" "$BOARD"
elif [ -f "$TMP_PAYLOAD/update-bananapi-branding.sh" ] && [ "$BOARD" = "bananapi-m8" ]; then
  echo "[*] Executing Banana Pi branding script..."
  chmod +x "$TMP_PAYLOAD/update-bananapi-branding.sh"
  "$TMP_PAYLOAD/update-bananapi-branding.sh" "$MNT" "$BOARD"
fi

# Dual console autologin configuration (tty1, tty2, ttyS0, and default getty@)
echo "[*] Configuring serial & display autologin for $LOGIN_USER..."
rm -f "$MNT/etc/systemd/system/serial-getty@'ttyS0'.service" 2>/dev/null || true

# 1. Generic getty@ and serial-getty@ overrides
mkdir -p "$MNT/etc/systemd/system/getty@.service.d"
cat << GETTY_GEN > "$MNT/etc/systemd/system/getty@.service.d/override.conf"
[Service]
ExecStart=
ExecStart=-/sbin/agetty -o '-p -- \\u' --noclear --autologin $LOGIN_USER %I \$TERM
Type=idle
GETTY_GEN

mkdir -p "$MNT/etc/systemd/system/serial-getty@.service.d"
cat << SGETTY_GEN > "$MNT/etc/systemd/system/serial-getty@.service.d/override.conf"
[Service]
ExecStart=
ExecStart=-/sbin/agetty -o '-p -- \\u' --keep-baud --autologin $LOGIN_USER 115200,38400,9600 %I \$TERM
Type=idle
SGETTY_GEN

# 2. Specific tty1 override
mkdir -p "$MNT/etc/systemd/system/getty@tty1.service.d"
cat << TTY1_EOF > "$MNT/etc/systemd/system/getty@tty1.service.d/override.conf"
[Unit]
After=systemd-user-sessions.service plymouth-quit-wait.service
After=rc-local.service

[Service]
ExecStart=
ExecStart=-/sbin/agetty -o '-p -- \\u' --noclear --autologin $LOGIN_USER %I \$TERM
Type=idle
Restart=always
RestartSec=0
TTY1_EOF

# 3. Specific tty2 override
mkdir -p "$MNT/etc/systemd/system/getty@tty2.service.d"
cat << TTY2_EOF > "$MNT/etc/systemd/system/getty@tty2.service.d/override.conf"
[Unit]
After=systemd-user-sessions.service

[Service]
ExecStart=
ExecStart=-/sbin/agetty -o '-p -- \\u' --noclear --autologin $LOGIN_USER %I \$TERM
Type=idle
Restart=always
RestartSec=0
TTY2_EOF

# 4. Specific serial-getty@ttyS0 override
mkdir -p "$MNT/etc/systemd/system/serial-getty@ttyS0.service.d"
cat << SGETTY_EOF > "$MNT/etc/systemd/system/serial-getty@ttyS0.service.d/override.conf"
[Service]
ExecStart=
ExecStart=-/sbin/agetty -o '-p -- \\u' --keep-baud --autologin $LOGIN_USER 115200,38400,9600 %I \$TERM
Type=idle
Restart=always
RestartSec=0
SGETTY_EOF

# Ensure symlinks in getty.target.wants
mkdir -p "$MNT/etc/systemd/system/getty.target.wants"
ln -sf /usr/lib/systemd/system/getty@.service "$MNT/etc/systemd/system/getty.target.wants/getty@tty1.service"
ln -sf /usr/lib/systemd/system/getty@.service "$MNT/etc/systemd/system/getty.target.wants/getty@tty2.service"
ln -sf /usr/lib/systemd/system/serial-getty@.service "$MNT/etc/systemd/system/getty.target.wants/serial-getty@ttyS0.service"

# Install switch-to-tty2 service to ensure HDMI active VT defaults to tty2
if [ -f "$TMP_PAYLOAD/switch-to-tty2.service" ]; then
  cp -f "$TMP_PAYLOAD/switch-to-tty2.service" "$MNT/etc/systemd/system/switch-to-tty2.service"
  mkdir -p "$MNT/etc/systemd/system/multi-user.target.wants"
  ln -sf /etc/systemd/system/switch-to-tty2.service "$MNT/etc/systemd/system/multi-user.target.wants/switch-to-tty2.service"
fi

# Set default target cleanly as a valid symlink to multi-user.target
rm -f "$MNT/etc/systemd/system/default.target"
ln -s /usr/lib/systemd/system/multi-user.target "$MNT/etc/systemd/system/default.target"
rm -f "$MNT/root/.not_logged_in_yet"

sync
echo "======================================================================"
echo "[✓] SUCCESS: All fixes applied cleanly! Bootsplash & spinner purged."
echo "    - Board: $BOARD (DTB: $DTB_NAME)"
echo "    - Universal sector 16 bootloader active"
echo "    - Dual console active (UART0 serial: ttyS0,115200 + HDMI display: tty1)"
echo "    - Bootsplash / Plymouth / Spinner: DISABLED"
echo "======================================================================"
exit 0
